from pathlib import Path
import pandas as pd,numpy as np,json
O=Path('outputs');d=pd.read_csv(O/'stage6_rbm6_gnomad_aligned.csv');q=pd.read_csv(O/'stage6_singlebrain_ext_rbm6_full_regional.tsv.gz',sep='\t');n_total=len(q);q=q[(q.fixed_sd>0)&q.Allele.notna()&(q.Allele.eq(q.ref)|q.Allele.eq(q.alt))].copy();q['pair']=q.apply(lambda r:''.join(sorted([str(r.ref),str(r.alt)])),axis=1);x=d.merge(q,on=['pos','pair'],suffixes=('','_brain'),validate='one_to_many');assert not x.rs.duplicated().any();x['brain_beta_anchor']=np.where(x.Allele==x.anchor_effect_allele,x.fixed_beta,-x.fixed_beta);x['brain_z_anchor']=x.brain_beta_anchor/x.fixed_sd;assert np.isfinite(x.brain_z_anchor).all();x.to_csv(O/'stage6_rbm6_brain_gnomad_aligned.csv',index=False);rec={'source_rows':n_total,'valid_effect_and_positive_fixed_se':len(q),'reference_disease_snp_count':len(d),'exact_matches':len(x),'lead_hfrs_present':bool(x.rs.eq('rs2282749').any()),'zero_se_model_snp_rs2353586_present':bool(x.rs.eq('rs2353586').any()),'statistic':'fixed beta and fixed SE matched; random-effect portal p not used','limitation':'SingleBrain donor/samples count is dataset-wide, gene-specific effective n unknown; source regional subset not full-file checksum verified'};(O/'stage6_rbm6_brain_gnomad_prepare_receipt.json').write_text(json.dumps(rec,indent=2)+'\n');print(json.dumps(rec,indent=2))
